/**
 * Imports narration generated by hand on elevenlabs.io. Two modes:
 *
 *   npm run voiceover:import -- narration.mp3          # ONE file with the whole script
 *   npm run voiceover:import -- <folder-with-clips>     # one clip per cue
 *
 * Single file: the script is force-aligned to the audio (scripts/align-voiceover.py,
 * needs `pip install pocketsphinx`), giving word-level timestamps. The file is then
 * split at the pauses between cues, so captions and animations sync to the word.
 *
 * Folder of clips:
 * Matching:
 *   - Files whose names contain c01 … c31 are matched by that number.
 *   - Otherwise, if the folder holds exactly one file per cue, files are matched in
 *     name order. ElevenLabs downloads are timestamped, so generating the lines in
 *     order c01 → c31 makes name order correct. The mapping is printed so you can check it.
 *
 * Each clip has leading/trailing silence trimmed so the timeline stays tight, is
 * re-encoded to public/voiceover/<cue>.mp3, and its real duration goes into the
 * manifest. Manual clips have no word timestamps, so words are spread evenly
 * across each clip's real duration.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, mkdtempSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { CUES } from "../src/script.ts";

const ROOT = path.resolve(import.meta.dirname, "..");
const OUT_DIR = path.join(ROOT, "public", "voiceover");
const MANIFEST_PATH = path.join(ROOT, "src", "voiceover", "manifest.json");
const AUDIO = /\.(mp3|wav|m4a|ogg|flac|aac)$/i;

const input = process.argv[2];
if (!input) {
  console.error("Usage: npm run voiceover:import -- <narration.mp3 | folder-with-clips>");
  process.exit(1);
}

const ffmpeg = (args: string[]) => execFileSync("ffmpeg", ["-y", "-loglevel", "error", ...args]);
const probe = (file: string) =>
  parseFloat(
    execFileSync("ffprobe", ["-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", file], {
      encoding: "utf8",
    }).trim(),
  );
const writeManifest = (source: string, cues: Record<string, unknown>) => {
  writeFileSync(MANIFEST_PATH, JSON.stringify({ generated: true, source, cues }, null, 2) + "\n");
  const total = Object.values(cues as Record<string, { duration: number }>).reduce((s, c) => s + c.duration, 0);
  console.log(`\nWrote ${path.relative(ROOT, MANIFEST_PATH)} · spoken audio ${total.toFixed(1)}s`);
};
mkdirSync(OUT_DIR, { recursive: true });

if (statSync(input).isFile()) {
  importSingleFile(input);
  process.exit(0);
}
const dir = input;

const files = readdirSync(dir)
  .filter((f) => AUDIO.test(f))
  .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

const byId = new Map<string, string>();
for (const f of files) {
  const m = f.match(/(?:^|[^a-z0-9])c(\d{1,2})(?:[^0-9]|$)/i) ?? f.match(/^c(\d{1,2})/i);
  if (m) byId.set(`c${m[1].padStart(2, "0")}`, f);
}

let mapping: [string, string][];
if (CUES.every((c) => byId.has(c.id))) {
  mapping = CUES.map((c) => [c.id, byId.get(c.id)!]);
} else if (files.length === CUES.length) {
  console.log("Files are not named c01…c31, so they are matched in name order:\n");
  mapping = CUES.map((c, i) => [c.id, files[i]]);
} else {
  const missing = CUES.filter((c) => !byId.has(c.id)).map((c) => c.id);
  console.error(
    `Found ${files.length} audio files, expected ${CUES.length}.\n` +
      (byId.size ? `Missing cues: ${missing.join(", ")}\n` : "") +
      "Name the files c01.mp3 … c31.mp3, or provide exactly one file per cue in order.",
  );
  process.exit(1);
}

const cues: Record<string, { file: string; duration: number; hash: string; words: never[] }> = {};

// Trim silence at both ends (via reverse), keep 60ms of air, normalise to 44.1k mono-safe MP3.
const TRIM =
  "silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.06," +
  "areverse,silenceremove=start_periods=1:start_threshold=-45dB:start_silence=0.06,areverse";

for (const [id, f] of mapping) {
  const src = path.join(dir, f);
  const file = `voiceover/${id}.mp3`;
  const dest = path.join(ROOT, "public", file);
  ffmpeg(["-i", src, "-af", TRIM, "-ar", "44100", "-codec:a", "libmp3lame", "-b:a", "192k", dest]);
  const duration = probe(dest);
  cues[id] = { file, duration: +duration.toFixed(3), hash: "manual", words: [] };
  const text = CUES.find((c) => c.id === id)!.text;
  console.log(`✓ ${id}  ${duration.toFixed(2).padStart(5)}s  ${f}\n      “${text}”`);
}

writeManifest("manual-clips", cues);

/** One narration file: align words, then cut each cue at the pauses around it. */
function importSingleFile(audio: string) {
  const tmp = mkdtempSync(path.join(os.tmpdir(), "vo-align-"));
  const cuesJson = path.join(tmp, "cues.json");
  const alignJson = path.join(tmp, "alignment.json");
  writeFileSync(cuesJson, JSON.stringify(CUES.map((c) => ({ id: c.id, text: c.text }))));
  const python = process.env.PYTHON ?? "python3";
  execFileSync(python, [path.join(ROOT, "scripts", "align-voiceover.py"), audio, cuesJson, alignJson], { stdio: "inherit" });
  const align: [number, number][][] = JSON.parse(readFileSync(alignJson, "utf8"));
  const total = probe(audio);

  const cues: Record<string, { file: string; duration: number; hash: string; words: { w: string; s: number; e: number }[] }> = {};
  CUES.forEach((cue, i) => {
    const words = align[i];
    const first = words[0][0];
    const last = words[words.length - 1][1];
    const prevEnd = i > 0 ? align[i - 1][align[i - 1].length - 1][1] : 0;
    const nextStart = i < CUES.length - 1 ? align[i + 1][0][0] : total;
    // Cut in the middle of the surrounding pauses, but never more than a breath away from the words.
    const start = Math.max(prevEnd + (first - prevEnd) / 2, first - 0.12, 0);
    const end = Math.min(last + (nextStart - last) / 2, last + 0.2, total);

    const file = `voiceover/${cue.id}.mp3`;
    ffmpeg(["-ss", start.toFixed(3), "-to", end.toFixed(3), "-i", audio, "-ar", "44100", "-codec:a", "libmp3lame", "-b:a", "192k", path.join(ROOT, "public", file)]);
    const tokens = cue.text.split(/\s+/);
    cues[cue.id] = {
      file,
      duration: +probe(path.join(ROOT, "public", file)).toFixed(3),
      hash: "aligned",
      words: tokens.map((w, k) => ({ w, s: +(words[k][0] - start).toFixed(3), e: +(words[k][1] - start).toFixed(3) })),
    };
    console.log(`✓ ${cue.id}  ${start.toFixed(2).padStart(6)}–${end.toFixed(2).padStart(6)}s  ${cue.text}`);
  });
  writeManifest(`aligned:${path.basename(audio)}`, cues);
}
